/* Original Drive assets, composited without repainting their pixels. */
function driveWindow(file,box,view,fit="none"){const m=driveAssets[file],b=view||m.bounds;return `<svg x="${box[0]}" y="${box[1]}" width="${box[2]}" height="${box[3]}" viewBox="${b[0]} ${b[1]} ${b[2]-b[0]} ${b[3]-b[1]}" preserveAspectRatio="${fit}" overflow="hidden"><image href="assets/drive/${file}" width="${m.size[0]}" height="${m.size[1]}"/></svg>`}
function drivePicture(file,cls=''){const m=driveAssets[file],b=m.bounds;return `<svg class="${cls}" viewBox="${b[0]} ${b[1]} ${b[2]-b[0]} ${b[3]-b[1]}" aria-hidden="true" focusable="false"><image href="assets/drive/${file}" width="${m.size[0]}" height="${m.size[1]}"/></svg>`}
const roomPNGs=['Agora','cinema','musica','sport-v2','anime-serie','cultura','teatro','gaming'];
const surfaceKinds=['ruvida','fine','fine','liscia','ruvida','ruvida','ruvida','liscia'];
const iconPNGs={home:'stanze',chat:'chat',user:'profilo',back:'indietro',filters:'filtri',mic:'microfono',volume:'audio',check:'conferma',close:'chiudi',more:'altro',phone:'termina'};
for(const [key,file] of Object.entries(iconPNGs))icons[key]=driveWindow(`Voemi_Icona_${file}.png`,[2,2,20,20],null,"xMidYMid meet");
icons.chevron=`<g transform="rotate(180 12 12)">${icons.back}</g>`;
paperBrand=function(){return drivePicture('Voemi_Logo_simbolo.png','paper-mark')+'<span>Voemi</span>'};
loadArt=function(){document.querySelectorAll('[data-art]').forEach(el=>{el.style.backgroundImage='none';el.innerHTML=drivePicture(`Voemi_Categoria_${roomPNGs[Number(el.dataset.art)]}.png`,'original-scene')})};
paperLayer=function(el){
 const w=el.clientWidth,h=el.clientHeight;if(!w||!h)return;
 if(el.matches('.paper-card,.large-art')){
  const i=Number(el.dataset.room??el.dataset.art);
  el.dataset.paper=paperFiles[i];originalCategoryPaperLayer(el);
  const colors=['eed5c4','e6c3cb','dacde8','cbdedb','ddd0ec','eddfb8','e7c9d4','cfdbbc'];
  const rgb=colors[i].match(/../g).map(hex=>parseInt(hex,16)/247),layer=el.querySelector(':scope > .material-layer'),id=`room-tint-${++materialId}`;
  layer.innerHTML=`<defs><filter id="${id}" color-interpolation-filters="sRGB"><feComponentTransfer><feFuncR type="linear" slope="${rgb[0]}"/><feFuncG type="linear" slope="${rgb[1]}"/><feFuncB type="linear" slope="${rgb[2]}"/></feComponentTransfer></filter></defs><g filter="url(#${id})">${layer.innerHTML}</g>`;
  return;
 }
 let file='Voemi_Superficie_carta-fine.png';
 if(el.matches('.footer-paper-outline'))file='Voemi_Superficie_carta-fine.png';
 else if(el.matches('.paper-card,.large-art'))file=`Voemi_Superficie_carta-${surfaceKinds[Number(el.dataset.room??el.dataset.art)]}.png`;
 else if(el.matches('#mobile-nav'))file='Voemi_Barra_navigazione.png';
 else if(el.matches('.png-input-shell'))file='Voemi_Campo_input.png';
 else if(el.matches('.primary,.interest.selected,.choice.selected,.inbox-tabs .selected,.bubble.mine,.composer button'))file='Voemi_Pulsante_scuro_prugna.png';
 else if(el.matches('button,.call .control>span,.pill,.duration-seal'))file='Voemi_Superficie_carta-fine.png';
 const lightPaper=file==='Voemi_Superficie_carta-fine.png';
 el.classList.toggle('light-paper-edge',lightPaper);
 if(el.matches('.call .control.end>span')){el.querySelector(':scope > .material-layer')?.remove();el.classList.remove('has-material');return;}
 const m=driveAssets[file],b=m.bounds,sw=b[2]-b[0],sh=b[3]-b[1];
 const long=sw/sh>2,cutX=long?sh*.45:150,cutY=long?sh*.45:150;
 const r=Math.min(lightPaper?12:long?h/2:22,w/2,h/2),xs=[0,cutX,sw-cutX,sw],ys=[0,cutY,sh-cutY,sh],dx=[0,r,w-r,w],dy=[0,r,h-r,h];
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('material-layer');svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');
 let parts='';for(let y=0;y<3;y++)for(let x=0;x<3;x++)if(dx[x+1]>dx[x]&&dy[y+1]>dy[y])parts+=driveWindow(file,[dx[x],dy[y],dx[x+1]-dx[x]+.1,dy[y+1]-dy[y]+.1],[b[0]+xs[x],b[1]+ys[y],b[0]+xs[x+1],b[1]+ys[y+1]]);
 svg.innerHTML=parts;el.querySelector(':scope > .material-layer')?.remove();el.prepend(svg);el.classList.add('has-material');el.dataset.pngSurface=file;
};
const previousDriveMaterials=applyMaterials;
applyMaterials=function(){
 document.querySelectorAll('input,select').forEach(input=>{if(input.closest('.png-input-shell'))return;const wrap=document.createElement('span');wrap.className='png-input-shell';input.before(wrap);wrap.append(input)});
 previousDriveMaterials();
 document.querySelectorAll('.png-input-shell').forEach(el=>{materialObserver.observe(el);paperLayer(el)});
 document.querySelectorAll('.brand').forEach(el=>el.innerHTML=state.view==='onboarding'?drivePicture('Voemi_Logo_logo.png','full-paper-logo'):paperBrand());
};
toggleMute=function(){state.muted=!state.muted;const b=document.getElementById('mute');b.classList.toggle('toggled',state.muted);b.setAttribute('aria-pressed',String(state.muted));b.querySelector('label').textContent=state.muted?'Riattiva':'Microfono';b.querySelector('span > svg:not(.material-layer)').innerHTML=driveWindow(`Voemi_Icona_${state.muted?'muto':'microfono'}.png`,[2,2,20,20],null,"xMidYMid meet");document.querySelector('.voice-orb').classList.toggle('paused',state.muted)};
callOptions=function(){panel('Opzioni della chiamata',`<button class="secondary" onclick="state.speaker=!state.speaker;callOptions()">${icon('volume')}Audio ${state.speaker?'attivo':'spento'} · ${state.speaker?'disattiva':'attiva'}</button><button class="secondary" onclick="safetyPanel()">Sicurezza · blocca o segnala</button>`)};
render();

// Keep one paper frame and animate its position across footer sections.
const footerPaperFrame=document.createElement('span');
footerPaperFrame.className='footer-paper-outline';
footerPaperFrame.setAttribute('aria-hidden','true');
let footerPaperIndex=0,footerPaperReady=false;
const navWithDriveAssets=nav;
nav=function(){
 const footer=document.getElementById('mobile-nav');
 const wasVisible=footer.clientHeight>0&&!document.body.classList.contains('no-bottom-nav');
 const previous=footerPaperIndex;
 navWithDriveAssets();
 const buttons=[...footer.querySelectorAll('button')];
 footerPaperIndex=Math.max(0,buttons.findIndex(button=>button.classList.contains('active')));
 footer.append(footerPaperFrame);
 footerPaperFrame.style.transform=`translateX(${footerPaperIndex*100}%)`;
 paperLayer(footerPaperFrame);
 if(footerPaperReady&&wasVisible&&previous!==footerPaperIndex&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
  footerPaperFrame.getAnimations().forEach(animation=>animation.cancel());
  footerPaperFrame.animate([{transform:`translateX(${previous*100}%)`},{transform:`translateX(${footerPaperIndex*100}%)`}],{duration:360,easing:'cubic-bezier(.22,.8,.25,1)'});
 }
 footerPaperReady=true;
};
materialObserver.observe(footerPaperFrame);
nav();
